import { Image, StyleSheet, View } from 'react-native';
import splashIcon from '../../assets/splash-icon.png';

/**
 * The Babelish mascot mark: a smiling polar bear wrapped in a speech-bubble
 * ribbon beneath three multilingual speech bubbles ("A", "文", "ض") and
 * speaking soundwaves.
 *
 * Rendered from the canonical `assets/splash-icon.png` generated by
 * `scripts/brand/generate-icons.py` so the launcher icon, native splash,
 * animated splash, and auth/onboarding headers share the exact same brand mark.
 */
export function BrandMark({
  size = 28,
}: {
  size?: number;
  tone?: 'dark' | 'light';
}) {
  return (
    <View
      style={{ width: size, height: size }}
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
    >
      <Image
        source={splashIcon}
        style={styles.image}
        resizeMode="contain"
        accessibilityIgnoresInvertColors
      />
    </View>
  );
}

const styles = StyleSheet.create({
  image: {
    width: '100%',
    height: '100%',
  },
});
